export const lineWidth = 150;
export const indentation = "    ";

export const cppMarker =
  "// Generated by src/codegen/aot-schema/index.ts in Bun from aot/ir/AOTSchema.def. Do not edit.";
export const rustMarker =
  "// Generated by src/codegen/aot-schema/index.ts from JavaScriptCore/aot/ir/AOTSchema.def. Do not edit.";

export type Lines = readonly string[];

export function pack(items: Lines, indent: string, separator = " ", width = lineWidth): string[] {
  const lines: string[] = [];
  for (const item of items) {
    const last = lines.length - 1;
    if (last >= 0 && lines[last].length + separator.length + item.length <= width) lines[last] += separator + item;
    else lines.push(indent + item);
  }
  return lines;
}

export function withCommas(items: Lines): string[] {
  return items.map((item, index) => (index + 1 < items.length ? `${item},` : item));
}

export function braced(head: string, items: Lines, tail = "};", indent = ""): string[] {
  if (items.length === 0) return [`${indent}${head} { ${tail}`];
  const oneLine = `${indent}${head} { ${withCommas(items).join(" ")} ${tail}`;
  if (oneLine.length <= lineWidth) return [oneLine];
  return [`${indent}${head} {`, ...pack(withCommas(items), indent + indentation), `${indent}${tail}`];
}

export function delimited(open: string, items: Lines, close: string, indent = ""): string[] {
  const oneLine = `${indent}${open}${items.join(" ")}${close}`;
  if (items.length === 0 || oneLine.length <= lineWidth) return [oneLine];
  return [`${indent}${open}`, ...pack(items, indent + indentation), `${indent}${close}`];
}

export function blocks(...parts: readonly Lines[]): string[] {
  const lines: string[] = [];
  for (const part of parts) {
    if (part.length === 0) continue;
    if (lines.length > 0) lines.push("");
    lines.push(...part);
  }
  return lines;
}

export function indent(lines: Lines, levels = 1): string[] {
  const prefix = indentation.repeat(levels);
  return lines.map(line => (line === "" ? "" : prefix + line));
}

function includeRank(include: string): number {
  return include.startsWith('"') ? 0 : 1;
}

function compareIncludes(left: string, right: string): number {
  return includeRank(left) - includeRank(right) || (left < right ? -1 : left > right ? 1 : 0);
}

function insideFeatureGuard(includes: Lines, body: Lines): string[] {
  const sorted = [...includes].sort(compareIncludes);
  return [
    "#if ENABLE(AOT)",
    "",
    ...(sorted.length > 0 ? [...sorted.map(include => `#include ${include}`), ""] : []),
    ...(body.length > 0 ? [...body, ""] : []),
    "#endif // ENABLE(AOT)",
  ];
}

export function cppHeader(includes: Lines, body: Lines): string[] {
  return [cppMarker, "", "#pragma once", "", "#include <wtf/Platform.h>", "", ...insideFeatureGuard(includes, body)];
}

export function cppHeaderWithoutFeatureGuard(includes: Lines, body: Lines): string[] {
  const sorted = [...includes].sort(compareIncludes);
  return [cppMarker, "", "#pragma once", "", ...sorted.map(include => `#include ${include}`), "", ...body];
}

export function cppSource(includes: Lines, body: Lines): string[] {
  const [own, ...others] = includes;
  return [cppMarker, "", '#include "config.h"', `#include ${own}`, "", ...insideFeatureGuard(others, body)];
}

export function inNamespace(namespace: "Wire" | "Typed", body: Lines): string[] {
  return [
    `namespace JSC { namespace AOT { namespace ${namespace} {`,
    "",
    ...body,
    "",
    `} } } // namespace JSC::AOT::${namespace}`,
  ];
}

function caseLabels(enumName: string, labels: Lines, indent: string): string[] {
  return pack(
    labels.map(label => `case ${enumName}::${label}:`),
    indent,
  );
}

export interface SwitchCase {
  readonly label: string;
  readonly value: string;
}

export interface SwitchOptions {
  readonly signature: string;
  readonly subject: string;
  readonly enumName: string;
  readonly cases: readonly SwitchCase[];
  readonly defaultValue: string | "most common" | null;
  readonly qualifier?: "constexpr" | "inline" | "";
}

export function constexprSwitch(options: SwitchOptions): string[] {
  const { signature, subject, enumName, cases } = options;
  const groups = Map.groupBy(cases, switchCase => switchCase.value);
  const isMostCommon = options.defaultValue === "most common";
  const defaultValue = isMostCommon ? mostCommonValue(groups, cases.length) : options.defaultValue;
  const qualifier = options.qualifier ?? "constexpr";
  const head = qualifier === "" ? signature : `${qualifier} ${signature}`;
  const inCase = indentation + indentation;
  const lines = [head, "{", `${indentation}switch (${subject}) {`];
  for (const [value, members] of groups) {
    if (value === defaultValue) continue;
    const labels = members.map(member => member.label);
    lines.push(...caseLabels(enumName, labels, indentation), `${inCase}return ${value};`);
  }
  if (defaultValue === null) {
    lines.push(`${indentation}}`, `${indentation}RELEASE_ASSERT_NOT_REACHED_UNDER_CONSTEXPR_CONTEXT();`, "}");
  } else {
    lines.push(`${indentation}default:`, `${inCase}return ${defaultValue};`, `${indentation}}`, "}");
  }
  return lines;
}

function mostCommonValue(groups: ReadonlyMap<string, readonly SwitchCase[]>, total: number): string | null {
  if (total <= 16) return null;
  let best: string | null = null;
  let bestCount = 0;
  for (const [value, members] of groups) {
    if (members.length > bestCount) {
      best = value;
      bestCount = members.length;
    }
  }
  return best;
}

export interface CaseBody {
  readonly label: string;
  readonly body: Lines;
}

export function groupedCases(enumName: string, cases: readonly CaseBody[], indent = indentation): string[] {
  const lines: string[] = [];
  for (const members of Map.groupBy(cases, caseBody => caseBody.body.join("\n")).values()) {
    const labels = members.map(member => member.label);
    lines.push(...caseLabels(enumName, labels, indent));
    lines.push(...members[0].body.map(line => (line === "" ? "" : indent + indentation + line)));
  }
  return lines;
}

export function predicateSwitch(
  name: string,
  enumName: string,
  parameter: string,
  answers: readonly (readonly [string, boolean])[],
): string[] {
  const cases = [true, false].flatMap(answer =>
    answers.filter(([, value]) => value === answer).map(([label]) => ({ label, value: String(answer) })),
  );
  const signature = `bool ${name}(${enumName} ${parameter})`;
  return constexprSwitch({ signature, subject: parameter, enumName, cases, defaultValue: null });
}

export function macroLines(name: string, items: Lines): string[] {
  if (items.length === 0) return [`#define ${name}(v)`];
  const body = pack(
    items.map(item => `v(${item})`),
    indentation,
    " ",
    lineWidth - 2,
  );
  return [`#define ${name}(v) \\`, ...body.map((line, index) => (index + 1 < body.length ? `${line} \\` : line))];
}

export function cppLiteral(text: string): string {
  return `"${text.replaceAll("\\", "\\\\").replaceAll('"', '\\"')}"_s`;
}

export function toText(lines: Lines): string {
  return `${lines.join("\n")}\n`;
}
